#!/usr/bin/env bash
# Question 1: Deployment ${Q1_APP} does not serve its page. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: ConfigMap
metadata:
  name: ${Q1_APP}-content
  namespace: ${Q1_NS}
data:
  index.html: "<h1>${Q1_APP} is up</h1>"
---
apiVersion: v1
kind: Secret
metadata:
  name: ${Q1_APP}-secret
  namespace: ${Q1_NS}
stringData:
  token: s3cr3t-${Q1_APP}
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q1_APP}
  namespace: ${Q1_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q1_APP} }
  template:
    metadata:
      labels: { app: ${Q1_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          readinessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
          volumeMounts:
            - { name: content, mountPath: /usr/share/nginx/html }
            - { name: secret, mountPath: /etc/${Q1_APP}, readOnly: true }
      volumes:
        - name: content
          configMap: { name: ${Q1_APP}-content }
        - name: secret
          secret:
            secretName: ${Q1_APP}-secret
            items: [{ key: token, path: token }]
EOF

case "${Q1_FAULT}" in
  configmap-volume-missing)
    kubectl -n "${Q1_NS}" patch deployment "${Q1_APP}" --type=json -p '[{"op":"replace","path":"/spec/template/spec/volumes/0/configMap/name","value":"'"${Q1_APP}"'-contents"}]'
    ;;
  secret-items-key)
    kubectl -n "${Q1_NS}" patch deployment "${Q1_APP}" --type=json -p '[{"op":"replace","path":"/spec/template/spec/volumes/1/secret/items/0/key","value":"api-token"}]'
    ;;
  mount-path)
    kubectl -n "${Q1_NS}" patch deployment "${Q1_APP}" --type=json -p '[{"op":"replace","path":"/spec/template/spec/containers/0/volumeMounts/0/mountPath","value":"/usr/share/nginx"}]'
    ;;
  run-as-non-root)
    kubectl -n "${Q1_NS}" patch deployment "${Q1_APP}" --type=json -p '[{"op":"add","path":"/spec/template/spec/containers/0/securityContext","value":{"runAsNonRoot":true}}]'
    ;;
  readonly-root)
    kubectl -n "${Q1_NS}" patch deployment "${Q1_APP}" --type=json -p '[{"op":"add","path":"/spec/template/spec/containers/0/securityContext","value":{"readOnlyRootFilesystem":true}}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q1_NS}" scale "deployment/${Q1_APP}" --replicas=2
sleep 20
[[ "$(kubectl -n "${Q1_NS}" get deployment "${Q1_APP}" -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "${Q1_APP} is still healthy" >&2; exit 1; }
